{
  "summary": "The function fn_14 processes input data and writes output to a buffer based on specific conditions.",
  "proposed_name": "fn_14",
  "algorithm": "unknown",
  "self_confidence": 0.8,
  "claims": [
    {
      "id": "1",
      "type": "CONST",
      "text": "The function uses the string 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B' for generating output.",
      "asserted_values": [],
      "confidence": 0.9
    },
    {
      "id": "2",
      "type": "IO",
      "text": "Returns VERA_ERR when out_cap is smaller than len.",
      "asserted_values": [],
      "confidence": 0.9,
      "io": {
        "when": "out_cap < len",
        "returns": "ERR"
      }
    },
    {
      "id": "3",
      "type": "SIDE",
      "text": "Writes exactly len bytes to out and never modifies in.",
      "asserted_values": [],
      "confidence": 0.9
    },
    {
      "id": "4",
      "type": "CF",
      "text": "The function has a loop that processes input data in chunks of 3 bytes.",
      "asserted_values": [],
      "confidence": 0.8
    },
    {
      "id": "5",
      "type": "CF",
      "text": "The function handles cases where len is 1 or 2 bytes separately after the main loop.",
      "asserted_values": [],
      "confidence": 0.8
    }
  ],
  "recovered_c": "uint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  size_t i = 0;\n  while (i < len) {\n    uint32_t value = (in[i] << 16) | (in[i + 1] << 8) | in[i + 2];\n    if ((len + 1) * len & 1) != 0 || arg != 0) {\n      value = ((len << 7) ^ value) * 0x2d6b + 0x12345678;\n      value = value >> 11 ^ value;\n    }\n\n    out[i * 2] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[value >> 20 & 0x3f];\n    out[i * 2 + 1] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[value >> 12 & 0x3f];\n\n    i += 3;\n  }\n\n  if (len % 3 == 1) {\n    out[len * 2] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[in[len - 1] >> 4];\n    out[len * 2 + 1] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[in[len - 1] >> 2];\n    out[len * 2 + 2] = 0x3d;\n    return len * 2 + 3;\n  } else if (len % 3 == 2) {\n    uint32_t value = (in[len - 2] << 8) | in[len - 1];\n    out[len * 2] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[value >> 12 & 0x3f];\n    out[len * 2 + 1] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[value >> 4 & 0x3f];\n    out[len * 2 + 2] = 'AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B'[value & 0xf0];\n    out[len * 2 + 3] = 0x3d;\n    return len * 2 + 4;\n  }\n\n  return len * 2;\n}"
}
